"""Build the consolidated experiment report from saved, audited measurements."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads((ROOT/p).read_text())
a=read('results/omega_window_study/summary.json');bench=read('results/lerobot_8gpu_4fps_ov36/summary.json');measure=read('results/lerobot_8gpu_4fps_ov36/measurement.json');ego=read('results/omega_window_study/ego_performance.json');rs=[r['metrics'] for r in measure['records']]
sums={k:sum(r[k] for r in rs) for k in ['task_wall_s','inference_s','upload_s','end_to_end_s','upload_and_stack_s','stitch_s','save_s']}
sums['decode_preprocess_other_s']=sums['end_to_end_s']-sums['inference_s']-sums['upload_and_stack_s']-sums['stitch_s']
sums['other_s']=sums['task_wall_s']-sums['end_to_end_s']-sums['upload_s']-sums['save_s']
lines=['# camera pose消融试验记录报告','','记录日期：2026-09-09。用途：为 WAM / VideoGEN 等下游提供相机轨迹；本报告区分已完成实验、工程选择及尚未验证的加速方案。','', '## 一、结论','', '1. **模型选择 VGGT-Omega。** 在既有20条HOT3D方法比较中，Ω的轨迹误差明显低于当前VGG-T³配置。此结论限于本地实现、权重和评估设置。', '2. **批量生产采用4fps、240帧窗口、36帧overlap，步长204帧。** 对应60秒窗口、9秒重叠、51秒步长。它是综合成本后的生产选择；精度优先时，现有实验更支持8fps/overlap48。不能把4fps/36描述成精度最优或通过原先8fps近优质量门槛。', f"3. **当前八卡整机外推约{bench['video_hours_per_machine_day']:.0f}视频小时/天，平均每卡约{bench['video_hours_per_gpu_day_average']:.0f}小时/天。** 统一{bench['wall_s']:.2f}秒完成{bench['completed']}条、累计{bench['video_s']/3600:.3f}小时原视频，包含BOS上传及逐条回读校验，失败0。平均每卡值来自八卡同时运行，不是独立单卡10分钟实测。", '4. **有明确的流水线加速空间，优先级高于盲目增大batch。** 当前任务墙钟约48.8%在推理路径、33.6%在BOS传输与校验、14.6%在解码/预处理等。应先消除GPU等待，再验证短L3独立batch推理。', '5. 输出平移仍是任意尺度；评估中的厘米误差经过Sim(3)对齐，不表示模型已恢复真实米制尺度。LeRobot测试只验证吞吐和产物完整性，没有GT精度结论。', '', '## 二、fps与overlap等消融试验','', '### 2.1 方法比较：独立的早期基准','', '同批20条HOT3D，每条前60秒、4fps，在采样观测位置评价；该阶段与后续完整视频/稠密30fps协议不同，不直接比较旋转RPE数值。','', '| 方法 | 完成 | ATE micro RMSE/cm | 1秒旋转RPE/° |','|---|---:|---:|---:|','| VGGT-Omega | 20/20 | 1.25 | 0.57 |','| VGG-T³，1次更新 | 20/20 | 25.19 | 22.94 |','| VGG-T³，2次更新 | 20/20 | 8.20 | 3.05 |','', 'Ω因此作为后续消融及生产模型。原始证据：[方法比较报告](results/REPORT.md)。相机专用路径关闭深度头，但不裁剪主干相机计算。', '', '### 2.2 完整视频消融协议','', '- 同批20条HOT3D完整连续视频，总计2442.5秒；2/4/8fps × overlap24/36/48，共180组，固定窗口最大240帧，允许自然短尾窗。', '- 每个配置插值到完全相同的30fps源帧时间轴，评价73145帧；只到所有配置共同覆盖的最后观测时刻，不外推。', '- ATE：逐视频全轨迹Sim(3)对齐后的稠密micro RMSE。尾段误差：只用前10秒拟合一次Sim(3)，评价最后15秒，随后不再用GT校正。', '- 重叠拼接不使用GT：相机朝向约束全局旋转，重叠中心估计尺度和平移，12轮稳健重加权；旋转和平移在重叠区融合。所有180组已用同一最终拼接版本复算。', '- 尾段误差也受前10秒运动与尺度可观测性影响，不能全部归因于拼接漂移。窗口大小固定240，没有比较120/480等窗口，因此不声称240是最优窗口。', '', '| fps | overlap/帧 | ATE/cm↓ | 1秒旋转RPE/°↓ | 尾段误差/cm↓ | 纯推理秒/视频分钟↓ |','|---:|---:|---:|---:|---:|---:|']
for r in a['summary']:lines.append(f"| {r['fps']} | {r['overlap']} | {r['ate_cm']:.3f} | {r['rpe_rot_deg']:.3f} | {r['anchor10_tail15_cm']:.3f} | {r['inference_s_per_video_minute']:.2f} |")
lines+=['', '表中纯推理成本为实测窗口耗时累加，共享缓存窗口也按完整逻辑成本计入各配置；不含数据准备、模型加载和BOS。它与后文原始LeRobot端到端吞吐口径不同。','', '### 2.3 fps结论','', '固定overlap36：2→4fps，ATE由2.089cm降至1.356cm，旋转RPE由3.925°降至1.438°，纯推理成本约翻倍；4→8fps，ATE变化较小（1.356→1.316cm），但旋转RPE进一步降至0.659°，纯推理成本约2.11倍。', '因此，4fps适合成本优先的常规批处理；8fps适合快速转头、快速运动、要求更细致旋转控制的片段。这里还包含稀疏姿态插值到30fps的误差，更密的输出插值本身不能弥补低采样率丢失的运动。16fps做过早期整段耗时尝试，但未纳入这180组窗口精度消融，不能声称16fps已做精度验证。', '', '### 2.4 overlap结论','', '固定4fps：24→36帧，ATE由1.437降至1.356cm，改善约5.7%，纯推理成本增加约3.5%；36→48帧，ATE进一步改善约6.0%，尾段误差改善约9.2%，纯推理成本再增加约4.1%。因此36是用户选定的生产折中，不是存在明显性能拐点的统计证明。', '固定8fps：48相对24帧的ATE改善17.4%，最差视频ATE改善39.3%，纯推理成本增加12.6%；这是先前精度优先建议8fps/48的依据。三个overlap的旋转RPE都约0.66°，不能声称48在旋转接缝上有明确优势。', '更大overlap的主要收益是增加对齐约束、改善部分视频的平移轨迹；短于一个窗口的视频不会触发拼接，overlap不会产生额外推理。4fps下多数短L3片段因此不受overlap开销影响。', '8fps/48的精度优先选择包含完整逐条结果后的工程复核，并非预注册统计检验；当前4fps/36是随后明确采用的成本折中。原始门槛和所有逐条结果均保留。', '', '![fps与overlap消融](results/omega_window_study/configuration_comparison.png)', '', '详细协议和逐条证据：[窗口消融报告](results/omega_window_study/REPORT.md)、[协议](results/omega_window_study/PROTOCOL.md)、[逐配置汇总](results/omega_window_study/summary.csv)。', '', '## 三、耗时分析与统计','', '### 3.1 整段推理与窗口化的差别','', '早期不切窗时，ego_hand0723最长388.67秒视频在Ω 4/8/16fps默认配置下均OOM；4fps使用可扩展分配器后可完成，但峰值93.85GiB、纯推理336.63秒。OOM是具体实现及分配器的结果，不能解释成绝对容量上限。', '窗口化后，在8fps、240帧窗口下三个overlap均跑通全部11条ego视频（累计584.43秒），峰值19.39GiB。该组是8fps验证，不是4fps/36的LeRobot吞吐结果。','', '| overlap | 11条纯推理合计/s | 11条端到端合计/s | 最长389秒视频端到端/s |','|---:|---:|---:|---:|']
for r in ego:lines.append(f"| {r['overlap']} | {r['inference_total_s']:.2f} | {r['end_to_end_total_s']:.2f} | {r['longest_end_to_end_s']:.2f} |")
lines+=['', '此处端到端包括读取/预处理/上传GPU/推理/拼接，不包括模型加载、文件保存和BOS。最长视频输出3110个8fps观测姿态。', '', '### 3.2 LeRobot八卡实际吞吐','', '输入：`/mnt/pfs/pfs-yc2F4O/modelTeam/liberai-human-dataset/processed_lerobot/web_first_36K/dataset`。从128个chunk各随机抽32条，seed20260909，4096条组成随机顺序任务池。该方法是chunk分层抽样，chunk文件数不等时不等于全库严格均匀视频抽样。', 'GPU0–7各一个常驻Ω模型，共用HTTP任务server；CPU每worker设置6个torch线程，OpenBLAS单线程。GPU0原有约13GiB进程被保留。驱动名称为NVIDIA RPBZZZ6，约96GiB，计算能力12.0。', '', '| 项目 | 实测值 |','|---|---:|',f"| 统一稳态测量 | {bench['wall_s']:.2f}秒 |",f"| 成功视频 | {bench['completed']}条 |",f"| 原视频累计时长 | {bench['video_s']/3600:.3f}小时 |",f"| 八卡整机日吞吐外推 | {bench['video_hours_per_machine_day']:.1f}小时/天 |",f"| 平均每卡折算 | {bench['video_hours_per_gpu_day_average']:.1f}小时/天 |",'| 失败尝试 | 0 |','| 成功片段时长中位数 / P90 | 8.00秒 / 34.00秒 |','| 多窗口视频 / 最长视频 | 72条 / 473秒 |','| worker自身峰值allocated显存 | 17.01GiB |','| 模型加载及预热 | 每卡约15秒，未计入稳态区间 |', '', f"换算公式：{bench['video_s']:.2f} ÷ {bench['wall_s']:.2f} × 24 = {bench['video_hours_per_machine_day']:.1f} 视频小时/整机天。", '统计分子只计统一区间内server接受的完整任务；计时含PFS读取、解码/预处理、GPU推理、拼接、写出、BOS上传和逐条回读SHA256校验。起止边界可能有跨区间任务，采用持续运行完成吞吐口径，不为统计排空队列。', '该结果不是24小时持续运行测试，也不含从BOS下载源视频的成本。不能把1177小时/天直接迁移到长视频比例、分辨率、CPU或存储条件不同的数据集。原单卡600秒测试按最新要求中途切换八卡，没有完整独立单卡10分钟结论。', '', '### 3.3 逐阶段耗时拆解','', '以下为1771个被计数任务在八个worker上的阶段时间累加，单位为worker秒，不是整机墙钟秒。任务墙钟累计4762.86秒，与8×600.15秒略有差别，来自测量边界、领取/确认和任务间空隙；不能把两者混为一谈。','', '| 阶段 | 累计worker秒 | 占累计任务墙钟 |','|---|---:|---:|']
for name,key in [('推理路径（含相机解码及结果回CPU）','inference_s'),('BOS上传、回读与SHA256校验','upload_s'),('解码、预处理及该段其他未单列工作（差额）','decode_preprocess_other_s'),('输入stack与上传GPU','upload_and_stack_s'),('轨迹拼接','stitch_s'),('NPZ初次保存','save_s'),('任务目录、额外JSON/标记准备等其他差额','other_s')]:lines.append(f"| {name} | {sums[key]:.2f} | {sums[key]/sums['task_wall_s']*100:.2f}% |")
lines+=['', '“解码/预处理等”由端到端计时减去已单列阶段得到，不是独立精确CPU profiler测量。推理路径48.8%的占比也不是GPU硬件利用率；它包含同步、相机解码和结果回CPU。', 'BOS段平均约0.90秒/视频，而1771条NPZ+JSON合计仅约12.1MB；这提示小对象请求、命令启动及回读固定成本值得优化，但现有计时未把各项分开，不能直接断言网络带宽是瓶颈。', '', '![八卡吞吐](results/lerobot_8gpu_4fps_ov36/throughput.png)', '', '全部1771条的帧覆盖、数值和旋转矩阵检查通过，BOS NPZ/JSON逐条回读SHA256通过；32条额外ffprobe时长校验最大差异低于1微秒。3次重叠尺度回退有记录，不等于任务失败，也不能据此证明精度。', '详细证据：[八卡吞吐报告](results/lerobot_8gpu_4fps_ov36/REPORT.md)、[逐任务明细](results/lerobot_8gpu_4fps_ov36/per_video.csv)、[完整性审计](results/lerobot_8gpu_4fps_ov36/artifact_audit.json)。', '', '## 四、后续建议与加速路径','', '### 4.1 第一优先级：把读视频和上传移出GPU串行路径','', '当前每个worker是“读取/预处理→GPU推理→拼接保存→BOS上传回读→领下一条”。八卡之间并行，但单卡内部仍串行，GPU会等待前后处理。建议保持每卡一个模型，增加有界的CPU预取队列和异步结果上传队列：','', '```mermaid','flowchart LR','  S[任务server] --> D[CPU解码与预处理池]','  D --> Q[有界预取队列]','  Q --> G[GPU常驻模型]','  G --> P[CPU拼接与写出]','  P --> U[有界上传队列]','  U --> B[BOS上传与校验]','  B --> A[server完成确认]','```', '', '- 先做异步上传，让视频A的BOS传输与视频B的GPU推理重叠；上传成功之前继续维护A的租约，不能提前向server报告完成。上传失败保留本地结果并重试传输，避免重新跑GPU。', '- 再做CPU预解码与预处理，初始可每卡2个预取worker、2–4个待推理任务，但这些只是实验起点。必须按CPU图像缓存字节数和总帧数限流，长片段按窗口流式预取，不能预解码无界的完整视频。', '- 用预分配pinned host buffer、异步拷贝和独立CUDA copy stream/event管理依赖；只加`non_blocking=True`不足以保证拷贝与计算真正重叠。具体条件参考[PyTorch官方异步拷贝教程](https://docs.pytorch.org/tutorials/intermediate/pinmem_nonblock.html)。', '- 当前每条视频调用`empty_cache()`，每个窗口显式同步；应比较保留allocator缓存的收益，并把同步放到真正需要CPU消费结果的位置。异步改造后使用CUDA events和流水线总完成时长计时，避免为了计时又把流水线串行化。', '- 生产是否保留逐条BOS下载校验应单独选择；可以测试“上传成功+校验信息+抽样回读”，但这是校验强度变化，必须单独记录，不能把减少校验算成同口径流水线加速。优先保留现有校验来做公平对照。', '', '### 4.2 第二优先级：短L3做真正的独立batch','', '从本地源码检查，Ω的输入和主干支持`[B,T,3,H,W]`，global attention保留B维，各视频可独立推理。当前`benchmark_camera.predict()`却使用`extr[0]`和`k[0]`，只输出batch第0项；必须先改为完整保留B维，再按episode拆分输出、归一化和拼接。这里只完成源码可行性检查，尚未实测B>1的吞吐与数值一致性。', '', '**不要将多个无关L3沿T维拼成一个长视频。** 那会让跨视频帧相互注意，并错误共享场景与坐标关系。正确做法是沿B维堆叠，并保留各L3独立坐标系。', '', '初步实施顺序：', '1. 先用完全相同的T/H/W组成B=2、4、8的batch，分别测B=1串行对照，比较每个视频的相对旋转、相机中心与内参，并检查batch样本交换顺序不会串数据。', '2. 按帧数、长宽比分桶，提高同形状样本的可组batch率；长短片不要全部补到240帧。可以用T约16/32/64/128/240作为调度桶的起点，但桶边界不等于可以直接补帧。', '3. 当前模型forward未暴露帧padding mask。若把短片补帧后一起推理，必须贯通global/register等跨帧注意力的有效帧mask并验证结果；简单重复末帧或补零可能改变有效帧预测。优先先验证等长batch。', '4. batch按总token、估算计算量和显存预算动态限制；长片240帧窗口从B=1/2开始，短片逐步增加B。17GiB的单任务峰值不意味着96GiB显存就必然能高效跑5倍吞吐。', '', '显存未用满只说明容量有余量，不能证明算力没有饱和。batch可提高短序列的并行程度、减少部分调度开销，但也增加总计算与中间张量；长序列注意力和padding可能抵消收益，必须看完成视频秒数/墙钟秒数。', '代码依据：[模型forward](vggt_omega_repo/vggt_omega/models/vggt_omega.py)、[Aggregator](vggt_omega_repo/vggt_omega/models/aggregator.py)、[当前单样本解码封装](scripts/benchmark_camera.py)、[串行视频runner](scripts/run_omega_video.py)。', '', '### 4.3 加速幅度如何预期','', f"只把BOS阶段完全隐藏、其他成本不变，按聚合阶段时间粗算为 {sums['task_wall_s']/(sums['task_wall_s']-sums['upload_s']):.2f}×；若所有非推理阶段都能隐藏且推理成本不变，粗算约 {sums['task_wall_s']/sums['inference_s']:.2f}×。", '这两个数是理想化成本模型，不是实测收益、严格系统上界或承诺；未计入流水线填充/排空、资源争用、队列不均衡和新增开销，且“推理”计时本身也包含部分非GPU工作。batch收益另需实测，不能直接与理想倍数相乘。', '', '### 4.4 建议的后续对照实验','', '| 阶段 | 改动 | 要回答的问题 |','|---|---|---|','| A0 | 现有B=1串行，保持当前BOS回读校验 | 固定基线 |','| A1 | 仅异步上传，有界队列 | 传输等待能隐藏多少 |','| A2 | A1 + CPU预解码、预处理、异步H2D | GPU等待是否继续下降 |','| A3 | A2 + 同形状B=2/4/8 | batch能否提高真实完成吞吐 |','| A4 | 帧长分桶及必要的mask支持 | 不规则L3能否保持精度并提高batch效率 |', '', '每阶段用相同任务清单，先做数值与失败恢复检查，再做至少10–15分钟八卡同口径吞吐对照；最好多次重复或完成相同固定任务集合，避免恰好落在计时边界的长视频影响比较。保持BOS校验策略一致，记录端到端吞吐、推理/传输时间、队列等待、CPU/RAM/显存和失败率。A3/A4需回到20条GT数据验证精度，不能只看显存和速度。', '', '### 4.5 当前落地配置与产物','', '保持4fps/240/36作为当前生产基线，先做A1，再做A2，最后再做batch；不建议第一步就在同一GPU复制多个模型来“填满显存”。', '现有入口：[process_camera_lerobot.py](process_camera_lerobot.py)，server-client部署/续跑/追加任务说明：[PROCESS_CAMERA_LEROBOT.md](PROCESS_CAMERA_LEROBOT.md)。本报告未修改正在运行的worker，也未把上述加速预期写成已完成实验。', '临时结果BOS前缀：`/mnt/bos/liberai-web-humandata/processing/for_next_20260901_150304_249934232/temp_camera_motion/benchmark_20260909_8gpu_4fps_ov36/`。每条结果包含camera.npz、camera.json和SUCCESS.json，精确测量区间的结果映射及报告在该前缀的`_benchmark/`目录。']
path=ROOT/'camera pose消融试验记录报告.md';path.write_text('\n'.join(lines)+'\n')
